const resultsCount = 91; // Total results you want
const items = [];

for (let i = 51; i <= resultsCount; i += 10) {
  items.push({ json: { start_index: i } });
}

return items;

// 1. Define a "Blocklist" of directory/social sites to ignore.
// These sites are hard to scrape or won't have the owner's email on the homepage.
const ignoreDomains = [
  "linkedin.com",
  "facebook.com",
  "justdial.com",
  "sulekha.com",
  "scribd.com",
  "advisorkhoj.com",
  "thinkingbridge.in",
  "instagram.com",
  "google.com"
];

let cleanLinks = [];

// 2. Loop through the input data
for (const item of items) {
  // Access the Google Search results array
  const googleResults = item.json.items || [];

  for (const result of googleResults) {
    const url = result.link;

    // 3. Check if the URL contains any of the "ignored" domains
    const isJunk = ignoreDomains.some(domain => url.includes(domain));

    // 4. If it's a REAL website, add it to our list
    if (url && !isJunk) {
      cleanLinks.push({
        json: {
          title: result.title,
          url: url
        }
      });
    }
  }
}

// 5. Remove Duplicates (Since your input had the same data repeated 3 times)
const uniqueLinks = cleanLinks.filter((value, index, self) =>
  index === self.findIndex((t) => (
    t.json.url === value.json.url
  ))
);

return uniqueLinks;

let allLeads = [];

// 1. Loop through the AI output
for (const item of items) {
  try {
    let rawText = item.json.text;

    // Safety: Remove any potential Markdown code blocks (```json) just in case
    if (rawText) {
      rawText = rawText.replace(/```json/g, "").replace(/```/g, "").trim();

      // 2. Parse the text string into real JSON data
      const parsedData = JSON.parse(rawText);

      // 3. Add these leads to our master list
      if (Array.isArray(parsedData)) {
        allLeads.push(...parsedData);
      }
    }
  } catch (error) {
    // If one block fails, we just skip it
    continue;
  }
}

// 4. Remove Duplicates (based on Email)
// Sometimes the search finds the same guy twice. We don't want duplicate rows.
const uniqueLeads = [];
const seenEmails = new Set();

for (const lead of allLeads) {
  if (lead.email && !seenEmails.has(lead.email)) {
    seenEmails.add(lead.email);

    // Format for n8n output
    uniqueLeads.push({
      json: {
        "Company Name": lead.company,
        "Email Address": lead.email,
        "Date Added": new Date().toISOString().split('T')[0], // Adds today's date
        "Status": "Ready"
      }
    });
  }
}

return uniqueLeads;
